  legal: (p, c) => '<section class="textblock legal"><div class="wrap narrow article">' + (p.title ? "<h2" + F("title", c.edit) + ">" + esc(p.title) + "</h2>" : "") + (p.updated ? '<p class="sub">Last updated: ' + esc(p.updated) + "</p>" : "") + '<div class="md">' + md(p.body || "") + "</div></div></section>",
