  social: (p, c) => '<section class="socialsec"><div class="wrap center">' + head(p, c.edit) + '<div class="btns soc-l">' + list(p.links, 10).filter((x) => safeUrl(x.href)).map((x) => '<a class="btn ghost" href="' + esc(safeUrl(x.href)) + '" rel="noopener" target="_blank" data-cta="' + esc(x.label) + '">' + esc(x.label) + "</a>").join("") + "</div></div></section>",
  embed: (p, c) => { const u = embedUrl(p.url); return '<section class="embed"><div class="wrap' + (p.wide ? "" : " narrow") + '">' + head(p, c.edit) + (u ? '<div class="emb" style="aspect-ratio:' + (/maps|calendly|typeform|forms/.test(u) ? "4/3" : "16/9") + '"><iframe src="' + esc(u) + '" title="' + esc(p.title || "Embedded content") + '" loading="lazy" referrerpolicy="no-referrer" allow="encrypted-media; picture-in-picture; fullscreen"></iframe></div>' : '<div class="ph" role="img" aria-label="Paste a YouTube, Vimeo, Google Maps, Calendly, Typeform, Google Forms or Spotify link"></div>') + "</div></section>"; },
  whatsapp: (p, c) => { const n = String(p.number || "").replace(/\D/g, ""); return '<section class="wa-band"><div class="wrap cta-in"><div>' + (p.title ? "<h2" + F("title", c.edit) + ">" + esc(p.title) + "</h2>" : "") + (p.text ? "<p>" + esc(p.text) + "</p>" : "") + "</div>" + (n ? '<a class="btn wa" href="https://wa.me/' + esc(n) + (p.message ? "?text=" + encodeURIComponent(p.message) : "") + '" rel="noopener" target="_blank" data-cta="WhatsApp">' + esc(p.button || "Chat on WhatsApp") + "</a>" : '<span class="sub">Add your WhatsApp number</span>') + "</div></section>"; },
